-- =====================================================================
-- komaroviqvizebi.ge  -  Duels (Phase 2)
-- Run in: Supabase Dashboard -> SQL Editor -> New query -> Run (safe to run again),
-- AFTER schema.sql, 02-daily-problem.sql and 03-daily-one-try.sql. Then run answer-key.sql
-- (generated by `node tools/build-answer-key.js`), and re-run it whenever quiz files change.
--
-- How a duel works:
--   * a logged-in student creates a duel (grade, optional topic group and difficulty,
--     5/10/15 problems). The SERVER picks the problems, so the creator can't look at
--     them in advance, and gets a 6-character code to share.
--   * a friend opens the link and accepts. Each player presses "start" whenever they want
--     before the duel expires (48 h after it was created); the timer is per player.
--   * answers are graded HERE (problem_keys, the private answer key shared with the daily
--     problem, is never readable from the browser) and times
--     come from the database clock, so neither can be faked from the browser console.
--   * more correct answers wins; equal -> less total time wins; equal -> draw.
--   * XP: win +30, draw +15, lost but played +5 (plus the normal +10 for a first-time
--     correct answer, because every duel answer is also saved through record_attempt()).
--
-- Privacy: the opponent sees only your username, avatar, score, time and (after the
-- duel) which problems you got right. Nothing else.
-- =====================================================================


-- ---------------------------------------------------------------------
-- 1. TABLES
-- ---------------------------------------------------------------------

-- The private answer key `problem_keys` already exists (02-daily-problem.sql). Duels need three
-- more columns for choosing problems; answer-key.sql (tools/build-answer-key.js) fills them.
alter table public.problem_keys
  add column if not exists area         text,                       -- null = untagged (not used in duels)
  add column if not exists topic_groups text[] not null default '{}', -- top-level topic ids from data/tags.json
  add column if not exists difficulty   smallint;

create table if not exists public.duels (
  id                 uuid primary key default gen_random_uuid(),
  code               text not null unique check (code ~ '^[A-Z0-9]{6}$'),
  created_by         uuid references auth.users (id) on delete set null,
  grade              smallint not null check (grade between 7 and 11),
  topic_group        text check (char_length(topic_group) <= 40),   -- null = any topic
  difficulty         smallint check (difficulty between 1 and 3),   -- null = any
  problem_ids        text[] not null,
  time_limit_seconds integer not null check (time_limit_seconds between 60 and 3600),
  status             text not null default 'open'
                       check (status in ('open', 'active', 'finished', 'expired')),
                       -- open = waiting for an opponent, active = two players, finished, expired = nobody accepted
  winner             uuid,                       -- null = draw (or expired)
  rematch_of         uuid references public.duels (id) on delete set null,
  created_at         timestamptz not null default now(),
  expires_at         timestamptz not null default now() + interval '48 hours',  -- last moment to accept / start
  finished_at        timestamptz
);
create index if not exists duels_status_idx on public.duels (status, expires_at);

-- One row per player (max 2). Score/time are filled when the player finishes.
create table if not exists public.duel_players (
  duel_id     uuid not null references public.duels (id) on delete cascade,
  user_id     uuid not null references auth.users (id) on delete cascade,
  joined_at   timestamptz not null default now(),
  started_at  timestamptz,
  finished_at timestamptz,
  score       smallint,                          -- correct answers
  total_ms    integer,                           -- time used, in milliseconds
  xp          smallint not null default 0,       -- duel XP given at the end
  primary key (duel_id, user_id)
);
create index if not exists duel_players_user_idx on public.duel_players (user_id, joined_at desc);

-- One row per answer. The primary key means: one answer per problem, no changing it.
create table if not exists public.duel_answers (
  duel_id     uuid not null,
  user_id     uuid not null,
  idx         smallint not null,                 -- 0-based position in duels.problem_ids
  answer      smallint not null check (answer between 0 and 5),
  is_correct  boolean not null,
  answered_at timestamptz not null default now(),
  primary key (duel_id, user_id, idx),
  foreign key (duel_id, user_id) references public.duel_players (duel_id, user_id) on delete cascade
);


-- ---------------------------------------------------------------------
-- 2. PERMISSIONS: the browser can't touch these tables at all.
--    Everything goes through the functions below (security definer).
-- ---------------------------------------------------------------------
revoke all on public.duels, public.duel_players, public.duel_answers
  from anon, authenticated;
alter table public.duels        enable row level security;
alter table public.duel_players enable row level security;
alter table public.duel_answers enable row level security;
-- (RLS on + no policies = no direct access, even if a grant is added by mistake later.)


-- ---------------------------------------------------------------------
-- 3. SETTINGS  (re-run a block with another number to change it)
-- ---------------------------------------------------------------------
create or replace function public.duel_seconds_per_problem()
returns integer language sql immutable as $$ select 120 $$;     -- 10 problems -> 20 minutes

-- Extra seconds accepted after the time limit (slow network).
create or replace function public.duel_grace_seconds()
returns integer language sql immutable as $$ select 10 $$;

create or replace function public.duel_xp(p_result text)
returns integer language sql immutable as $$
  select case p_result when 'win' then 30 when 'draw' then 15 when 'loss' then 5 else 0 end
$$;


-- ---------------------------------------------------------------------
-- 4. INTERNAL: bring a duel up to date (time-outs, expiry, final result, XP)
--    Called at the start of every duel function. Not callable from the browser.
-- ---------------------------------------------------------------------
create or replace function public.duel_settle(p_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  d       public.duels;
  a       public.duel_players;
  b       public.duel_players;
  v_n     integer;
  v_win   uuid;
  v_limit interval;
begin
  select * into d from public.duels where id = p_id for update;   -- one change at a time per duel
  if not found or d.status in ('finished', 'expired') then
    return;
  end if;
  v_limit := make_interval(secs => d.time_limit_seconds);

  -- players whose time ran out: finished at start + limit, score = what they answered right
  update public.duel_players p
     set finished_at = p.started_at + v_limit,
         total_ms    = d.time_limit_seconds * 1000,
         score       = (select count(*) from public.duel_answers x
                        where x.duel_id = p.duel_id and x.user_id = p.user_id and x.is_correct)
   where p.duel_id = d.id
     and p.started_at is not null
     and p.finished_at is null
     and now() > p.started_at + v_limit + make_interval(secs => public.duel_grace_seconds());

  if now() > d.expires_at then
    if d.status = 'open' then
      -- nobody accepted in time
      update public.duels set status = 'expired', finished_at = now() where id = d.id;
      return;
    end if;
    -- accepted, but a player never pressed start: counts as 0 points, full time
    update public.duel_players p
       set finished_at = d.expires_at, total_ms = d.time_limit_seconds * 1000, score = 0
     where p.duel_id = d.id and p.started_at is null and p.finished_at is null;
  end if;

  if d.status <> 'active' then
    return;
  end if;
  if exists (select 1 from public.duel_players where duel_id = d.id and finished_at is null) then
    return;                                     -- someone is still playing / hasn't played yet
  end if;

  -- both done: decide the winner
  select count(*) into v_n from public.duel_players where duel_id = d.id;
  if v_n = 2 then
    select * into a from public.duel_players where duel_id = d.id order by joined_at, user_id limit 1;
    select * into b from public.duel_players where duel_id = d.id order by joined_at, user_id offset 1 limit 1;
    -- someone who played beats someone who never started; then score; then time
    if (a.started_at is not null, a.score, -a.total_ms) > (b.started_at is not null, b.score, -b.total_ms) then
      v_win := a.user_id;
    elsif (a.started_at is not null, a.score, -a.total_ms) < (b.started_at is not null, b.score, -b.total_ms) then
      v_win := b.user_id;
    end if;                                     -- otherwise a draw (v_win stays null)

    update public.duel_players p
       set xp = public.duel_xp(case
                  when p.started_at is null then 'none'
                  when v_win is null        then 'draw'
                  when v_win = p.user_id    then 'win'
                  else 'loss' end)
     where p.duel_id = d.id;
    update public.profiles pr
       set xp = pr.xp + p.xp
      from public.duel_players p
     where p.duel_id = d.id and pr.id = p.user_id and p.xp > 0;
  end if;
  -- (v_n < 2 only if the other player deleted their account: no winner, no XP)

  update public.duels set status = 'finished', winner = v_win, finished_at = now() where id = d.id;
end;
$$;

-- Ends the caller's own game (all answered, "finish" button, or time up).
create or replace function public.duel_finish_player(p_id uuid, p_uid uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  d public.duels;
begin
  select * into d from public.duels where id = p_id;
  update public.duel_players p
     set finished_at = least(now(), p.started_at + make_interval(secs => d.time_limit_seconds)),
         total_ms    = least(d.time_limit_seconds * 1000,
                             round(extract(epoch from (now() - p.started_at)) * 1000)::integer),
         score       = (select count(*) from public.duel_answers x
                        where x.duel_id = p.duel_id and x.user_id = p.user_id and x.is_correct)
   where p.duel_id = p_id and p.user_id = p_uid
     and p.started_at is not null and p.finished_at is null;
end;
$$;


-- ---------------------------------------------------------------------
-- 5. FUNCTIONS FOR THE SITE
-- ---------------------------------------------------------------------

-- Creates a duel and returns { code, count }. The server picks the problems:
-- multiple-choice problems of the grade (and topic group / difficulty if given),
-- preferring ones the player(s) haven't tried yet, easier ones first.
-- p_rematch_of: a finished duel of the caller -> the same opponent is added right away.
create or replace function public.create_duel(
  p_grade       integer,
  p_count       integer,
  p_topic_group text    default null,
  p_difficulty  integer default null,
  p_rematch_of  uuid    default null
) returns json
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid     uuid := auth.uid();
  v_players uuid[];
  v_other   uuid;
  v_ids     text[];
  v_code    text;
  v_id      uuid;
  v_chars   constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';   -- no 0/O, 1/I
begin
  if v_uid is null then raise exception 'not logged in'; end if;
  if not exists (select 1 from public.profiles where id = v_uid) then raise exception 'no profile'; end if;
  if p_grade not between 7 and 11 then raise exception 'bad grade'; end if;
  if p_count not in (5, 10, 15) then raise exception 'bad count'; end if;
  if p_difficulty is not null and p_difficulty not between 1 and 3 then raise exception 'bad difficulty'; end if;
  if p_topic_group is not null and char_length(p_topic_group) > 40 then raise exception 'bad topic'; end if;

  -- at most 10 unfinished duels per student
  if (select count(*) from public.duel_players p join public.duels d on d.id = p.duel_id
      where p.user_id = v_uid and d.status in ('open', 'active') and d.expires_at > now()) >= 10 then
    raise exception 'too many open duels';
  end if;

  v_players := array[v_uid];
  if p_rematch_of is not null then
    if not exists (select 1 from public.duel_players p join public.duels d on d.id = p.duel_id
                   where p.duel_id = p_rematch_of and p.user_id = v_uid and d.status = 'finished') then
      raise exception 'bad rematch';
    end if;
    select user_id into v_other from public.duel_players
     where duel_id = p_rematch_of and user_id <> v_uid limit 1;
    if v_other is null then raise exception 'bad rematch'; end if;
    v_players := v_players || v_other;
  end if;

  select array_agg(problem_id order by difficulty nulls last, rnd) into v_ids
  from (
    select k.problem_id, k.difficulty, random() as rnd,
           exists (select 1 from public.attempts t
                   where t.user_id = any (v_players) and t.subject = 'math' and t.problem_id = k.problem_id) as seen
    from public.problem_keys k
    where k.grade = p_grade
      and k.has_options and cardinality(k.correct) > 0
      and k.area is not null                       -- tagged = shown on the duel page (data/problems.json)
      and (p_topic_group is null or p_topic_group = any (k.topic_groups))
      and (p_difficulty is null or k.difficulty = p_difficulty)
    order by seen, rnd
    limit p_count
  ) s;
  if coalesce(array_length(v_ids, 1), 0) < 3 then
    raise exception 'not enough problems';
  end if;

  loop                                         -- random unused code
    select string_agg(substr(v_chars, 1 + floor(random() * length(v_chars))::int, 1), '')
      into v_code from generate_series(1, 6);
    exit when not exists (select 1 from public.duels where code = v_code);
  end loop;

  insert into public.duels (code, created_by, grade, topic_group, difficulty, problem_ids,
                            time_limit_seconds, status, rematch_of)
  values (v_code, v_uid, p_grade, p_topic_group, p_difficulty, v_ids,
          array_length(v_ids, 1) * public.duel_seconds_per_problem(),
          case when v_other is null then 'open' else 'active' end, p_rematch_of)
  returning id into v_id;

  insert into public.duel_players (duel_id, user_id) values (v_id, v_uid);
  if v_other is not null then
    insert into public.duel_players (duel_id, user_id, joined_at) values (v_id, v_other, now() + interval '1 millisecond');
  end if;

  return json_build_object('code', v_code, 'count', array_length(v_ids, 1));
end;
$$;

-- Accepts an invitation. Returns the duel id.
create or replace function public.join_duel(p_code text)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  d     public.duels;
begin
  if v_uid is null then raise exception 'not logged in'; end if;
  if not exists (select 1 from public.profiles where id = v_uid) then raise exception 'no profile'; end if;
  select * into d from public.duels where code = upper(p_code) for update;
  if not found then raise exception 'no such duel'; end if;
  if exists (select 1 from public.duel_players where duel_id = d.id and user_id = v_uid) then
    return d.id;                               -- already in it
  end if;
  if d.status <> 'open' or now() > d.expires_at then raise exception 'duel not open'; end if;

  insert into public.duel_players (duel_id, user_id) values (d.id, v_uid);
  update public.duels set status = 'active' where id = d.id;
  return d.id;
end;
$$;

-- Starts the caller's timer (once). Problems become visible to the caller only now.
create or replace function public.start_duel(p_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  d     public.duels;
begin
  if v_uid is null then raise exception 'not logged in'; end if;
  select * into d from public.duels where id = p_id for update;
  if not found then raise exception 'no such duel'; end if;
  if d.status not in ('open', 'active') or now() > d.expires_at then raise exception 'duel closed'; end if;
  update public.duel_players set started_at = now()
   where duel_id = p_id and user_id = v_uid and started_at is null;
  if not found and not exists (select 1 from public.duel_players where duel_id = p_id and user_id = v_uid) then
    raise exception 'not a player';
  end if;
end;
$$;

-- Saves one answer, graded here. Returns { correct, finished } or { timeup: true }.
-- The answer is also saved as a normal attempt (mistakes notebook, progress, streak).
create or replace function public.duel_answer(p_id uuid, p_idx integer, p_answer integer)
returns json
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid     uuid := auth.uid();
  d         public.duels;
  p         public.duel_players;
  v_pid     text;
  v_correct boolean;
  v_prev    timestamptz;
  v_done    boolean := false;
begin
  if v_uid is null then raise exception 'not logged in'; end if;
  select * into d from public.duels where id = p_id for update;   -- lock the duel first (no deadlocks)
  if not found then raise exception 'no such duel'; end if;
  select * into p from public.duel_players where duel_id = p_id and user_id = v_uid;
  if not found then raise exception 'not a player'; end if;
  if p.started_at is null then raise exception 'not started'; end if;
  if p.finished_at is not null then raise exception 'already finished'; end if;

  if now() > p.started_at + make_interval(secs => d.time_limit_seconds + public.duel_grace_seconds()) then
    perform public.duel_settle(p_id);
    return json_build_object('timeup', true);
  end if;
  if p_idx < 0 or p_idx >= array_length(d.problem_ids, 1) then raise exception 'bad index'; end if;
  if p_answer < 0 or p_answer > 5 then raise exception 'bad answer'; end if;

  v_pid := d.problem_ids[p_idx + 1];
  select p_answer = any (k.correct) into v_correct from public.problem_keys k where k.problem_id = v_pid;
  v_correct := coalesce(v_correct, false);

  select max(answered_at) into v_prev from public.duel_answers where duel_id = p_id and user_id = v_uid;
  insert into public.duel_answers (duel_id, user_id, idx, answer, is_correct)
  values (p_id, v_uid, p_idx, p_answer, v_correct)
  on conflict do nothing;
  if not found then raise exception 'already answered'; end if;

  -- normal attempt + streak + first-correct XP (seconds since the previous answer / start)
  perform public.record_attempt(v_pid, p_answer::text, v_correct,
            round(extract(epoch from (now() - coalesce(v_prev, p.started_at))))::integer, 'math');

  if (select count(*) from public.duel_answers where duel_id = p_id and user_id = v_uid)
     >= array_length(d.problem_ids, 1) then
    perform public.duel_finish_player(p_id, v_uid);   -- answered everything
    v_done := true;
  end if;
  perform public.duel_settle(p_id);
  return json_build_object('correct', v_correct, 'finished', v_done);
end;
$$;

-- "Finish" button / time up: ends the caller's game now.
create or replace function public.finish_duel(p_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then raise exception 'not logged in'; end if;
  perform 1 from public.duels where id = p_id for update;
  if not found then raise exception 'no such duel'; end if;
  perform public.duel_finish_player(p_id, v_uid);
  perform public.duel_settle(p_id);
end;
$$;

-- Everything the duel page needs, as JSON (null if the code doesn't exist).
-- Guests (not logged in) get only the invitation preview.
-- The caller gets: problem ids once THEY started, the answer key once THEY finished,
-- and the opponent's answers only when the whole duel is finished.
create or replace function public.get_duel(p_code text)
returns json
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_id  uuid;
  d     public.duels;
  me    public.duel_players;
  opp   public.duel_players;
  v_preview json;
begin
  select id into v_id from public.duels where code = upper(p_code);
  if v_id is null then return null; end if;
  perform public.duel_settle(v_id);
  select * into d from public.duels where id = v_id;

  v_preview := json_build_object(
    'id', d.id, 'code', d.code, 'status', d.status, 'grade', d.grade,
    'topic_group', d.topic_group, 'difficulty', d.difficulty,
    'count', array_length(d.problem_ids, 1), 'time_limit', d.time_limit_seconds,
    'created_at', d.created_at, 'expires_at', d.expires_at, 'server_now', now(),
    'creator', (select json_build_object('username', username, 'avatar', avatar)
                from public.profiles where id = d.created_by),
    'players', (select count(*) from public.duel_players where duel_id = d.id));
  if v_uid is null then
    return v_preview;
  end if;

  select * into me  from public.duel_players where duel_id = d.id and user_id = v_uid;
  select * into opp from public.duel_players where duel_id = d.id and user_id <> v_uid
   order by joined_at limit 1;

  return (v_preview::jsonb || jsonb_build_object(
    'is_creator', d.created_by = v_uid,
    'is_player',  me.user_id is not null,
    'me', case when me.user_id is null then null else jsonb_build_object(
            'started_at', me.started_at, 'finished_at', me.finished_at,
            'score', me.score, 'total_ms', me.total_ms, 'xp', me.xp,
            'answers', coalesce((select jsonb_agg(jsonb_build_object('idx', idx, 'answer', answer, 'correct', is_correct) order by idx)
                                 from public.duel_answers where duel_id = d.id and user_id = v_uid), '[]'::jsonb)) end,
    'opponent', case when me.user_id is null or opp.user_id is null then null else jsonb_build_object(
            'username', (select username from public.profiles where id = opp.user_id),
            'avatar',   (select avatar   from public.profiles where id = opp.user_id),
            'started',  opp.started_at is not null,
            'finished', opp.finished_at is not null,
            'score',    case when d.status = 'finished' then opp.score end,
            'total_ms', case when d.status = 'finished' then opp.total_ms end,
            'xp',       case when d.status = 'finished' then opp.xp end,
            'answers',  case when d.status = 'finished' then
                          coalesce((select jsonb_agg(jsonb_build_object('idx', idx, 'answer', answer, 'correct', is_correct) order by idx)
                                    from public.duel_answers where duel_id = d.id and user_id = opp.user_id), '[]'::jsonb) end) end,
    'result', case when me.user_id is null or d.status <> 'finished' then null
                   when d.winner is null then 'draw'
                   when d.winner = v_uid then 'win' else 'loss' end,
    'problems', case when me.started_at is not null then to_jsonb(d.problem_ids) end,
    'keys', case when me.finished_at is not null then
              (select jsonb_agg(to_jsonb(k.correct) order by u.ord)
               from unnest(d.problem_ids) with ordinality as u (pid, ord)
               left join public.problem_keys k on k.problem_id = u.pid) end
  ))::json;
end;
$$;

-- The caller's duels, newest first (for the duel page and "my progress").
create or replace function public.my_duels(p_limit integer default 30)
returns json
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  r     record;
begin
  if v_uid is null then raise exception 'not logged in'; end if;
  -- bring unfinished ones up to date first (time-outs, expiry)
  for r in select d.id from public.duels d join public.duel_players p on p.duel_id = d.id
           where p.user_id = v_uid and d.status in ('open', 'active') loop
    perform public.duel_settle(r.id);
  end loop;

  return coalesce((
    select json_agg(x order by x.created_at desc) from (
      select d.code, d.status, d.grade, d.topic_group, d.difficulty, d.created_at, d.expires_at,
             array_length(d.problem_ids, 1) as count,
             me.started_at is not null  as started,
             me.finished_at is not null as finished,
             me.score, me.total_ms, me.xp,
             op.username as opp_username, op.avatar as opp_avatar,
             opp.started_at is not null as opp_started,
             case when d.status = 'finished' then opp.score end as opp_score,
             case when d.status <> 'finished' then null
                  when d.winner is null then 'draw'
                  when d.winner = v_uid then 'win' else 'loss' end as result
      from public.duel_players me
      join public.duels d on d.id = me.duel_id
      left join public.duel_players opp on opp.duel_id = d.id and opp.user_id <> v_uid
      left join public.profiles op on op.id = opp.user_id
      where me.user_id = v_uid
      order by d.created_at desc
      limit least(greatest(p_limit, 1), 100)
    ) x), '[]'::json);
end;
$$;


-- ---------------------------------------------------------------------
-- 6. WHO MAY CALL WHAT
-- ---------------------------------------------------------------------
-- internal helpers: nobody from the browser
revoke all on function public.duel_settle(uuid)              from public, anon, authenticated;
revoke all on function public.duel_finish_player(uuid, uuid) from public, anon, authenticated;

-- the site's functions: logged-in students (get_duel also guests, for the invitation preview)
revoke all on function public.create_duel(integer, integer, text, integer, uuid) from public, anon;
revoke all on function public.join_duel(text)                                    from public, anon;
revoke all on function public.start_duel(uuid)                                   from public, anon;
revoke all on function public.duel_answer(uuid, integer, integer)                from public, anon;
revoke all on function public.finish_duel(uuid)                                  from public, anon;
revoke all on function public.my_duels(integer)                                  from public, anon;
revoke all on function public.get_duel(text)                                     from public;

grant execute on function public.create_duel(integer, integer, text, integer, uuid) to authenticated;
grant execute on function public.join_duel(text)                                    to authenticated;
grant execute on function public.start_duel(uuid)                                   to authenticated;
grant execute on function public.duel_answer(uuid, integer, integer)                to authenticated;
grant execute on function public.finish_duel(uuid)                                  to authenticated;
grant execute on function public.my_duels(integer)                                  to authenticated;
grant execute on function public.get_duel(text)                                     to anon, authenticated;
